insert into data_layer_runs (layer_id, source, source_url, license, record_count, notes) values ($q$restricoes_rmsp$q$, $q$aguas-de-santa-barbara$q$, $q$https://camaraasb.sp.gov.br/?pag=T0dRPU9EZz1PR009T1RnPQ&id=1890&idtipolei=1 (Lei 1.842/2020)$q$, $q$Ato oficial do município: domínio público (Lei 9.610/1998 art. 8º IV). Zona aproximada pelos setores censitários urbanos do IBGE (Censo 2022, dados públicos, citar a fonte: IBGE) menos a travessia da SP-261 (vias do OpenStreetMap, ODbL 1.0, © colaboradores do OSM).$q$, 1, $q$Lei 1.842/2020: circulação de veículos extrapesados de carga (bitrens, tritrens, treminhões, rodotrens ou 18 t ou mais de PBT/PBTC) proibida nas vias urbanas do perímetro urbano, sem exceções. Perímetro sem delimitação no ato: setores urbanos do IBGE 2022, sem a travessia da SP-261.$q$);
